import csv, json
from pathlib import Path
from same_day_1445.live_optimizer.engine.forward_ledger import ForwardPositionBook, drain_pending_trades, append_pending_trade
from same_day_1445.live_optimizer.engine.signal_adapter import NormalizedSignal
from same_day_1445.live_optimizer.engine.orchestrator import run_optimizer
from same_day_1445.live_optimizer.engine.ledger import AppendOnlyCsvLedger

def test_closed_trade_keeps_opportunity_id_and_becomes_causal_at_maturity(tmp_path: Path):
    book=ForwardPositionBook(tmp_path/'positions.json');buy=NormalizedSignal('C','2026-08-24','BUY','510880','x',True,'OK','buy','',None,{'opportunity_id':'opp-1','regime':'neutral'});sell=NormalizedSignal('C','2026-08-25','SELL','510880','x',True,'OK','sell','',None,{'regime':'neutral'});assert book.apply('C','release_v2',buy,1.00,'2026-08-24T14:45:00+08:00') is None;trade=book.apply('C','release_v2',sell,1.10,'2026-08-25T14:45:00+08:00');assert trade['opportunity_id']=='opp-1';pending=tmp_path/'pending.jsonl';closed=tmp_path/'closed.csv';append_pending_trade(pending,trade);rows=drain_pending_trades(pending,closed,'2026-08-25T15:00:00+08:00');assert rows[0]['observable_at']=='2026-08-25T15:00:00+08:00';assert rows[0]['decision_at']=='2026-08-25T15:00:00+08:00'

def _optimizer_root(tmp_path: Path)->Path:
    root=tmp_path/'opt';(root/'config').mkdir(parents=True);(root/'state').mkdir();(root/'ledger').mkdir();cfg={'mode':'SHADOW_ONLY','cooldown_days':0,'gates':{'trigger_retention_min':0.9,'win_rate_delta_min':0.0,'mean_return_delta_min':-1.0,'max_drawdown_deterioration_max':1.0,'recent_windows_improve_fraction_min':0.0,'recent_window_win_rate_regression_max':1.0,'neighbor_pass_rate_min':0.0},'drift':{'recent_count':20},'lines':{x:{'minimum_new_samples':0,'minimum_regimes':0,'accounting':'research_sum' if x=='D' else 'compound'} for x in 'CSDR'},'candidate_spaces':{},'evaluation_windows':[{'name':'w','start':'2026-01-01','end':'2026-12-31'}]};(root/'config/optimizer.json').write_text(json.dumps(cfg),encoding='utf-8');return root

def test_optimizer_compares_candidate_only_to_same_matured_opportunities(tmp_path: Path):
    root=_optimizer_root(tmp_path);led=AppendOnlyCsvLedger(root/'ledger/closed_trades.csv',('sample_id','candidate_id'))
    for i,ret in enumerate((0.01,0.02,-0.50),1):led.append({'sample_id':f'b{i}','opportunity_id':f'o{i}','line':'C','candidate_id':'release_v2','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':f'2026-0{i}-01','exit_date':f'2026-0{i}-02','ret':ret,'triggered':1,'regime':'neutral'})
    for i,ret in ((1,0.02),(2,0.03)):led.append({'sample_id':f'c{i}','opportunity_id':f'o{i}','line':'C','candidate_id':'C_DELAY1','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':f'2026-0{i}-01','exit_date':f'2026-0{i}-02','ret':ret,'triggered':1,'regime':'neutral'})
    cand=run_optimizer(root,'2026-08-26T16:00:00+08:00')['lines']['C']['candidates'][0];assert cand['overall']['opportunities']==2;assert cand['gate']['evidence']['matched_baseline_opportunities']==2

def test_nontriggered_candidate_row_counts_against_trigger_retention(tmp_path: Path):
    root=_optimizer_root(tmp_path);led=AppendOnlyCsvLedger(root/'ledger/closed_trades.csv',('sample_id','candidate_id'))
    for i in range(1,3):led.append({'sample_id':f'b{i}','opportunity_id':f'o{i}','line':'D','candidate_id':'release_v2','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':'2026-02-01','exit_date':'2026-02-02','ret':0.01,'triggered':1,'regime':'weak'})
    led.append({'sample_id':'d1','opportunity_id':'o1','line':'D','candidate_id':'D_STRICT','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':'2026-02-01','exit_date':'2026-02-02','ret':0.02,'triggered':1,'regime':'weak'});led.append({'sample_id':'d2','opportunity_id':'o2','line':'D','candidate_id':'D_STRICT','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':'2026-02-01','exit_date':'2026-02-02','ret':0.0,'triggered':0,'regime':'weak'});cand=run_optimizer(root,'2026-08-26T16:00:00+08:00')['lines']['D']['candidates'][0];assert cand['overall']['opportunities']==2;assert cand['overall']['trades']==1;assert cand['overall']['trigger_retention']==0.5

def test_gate_rejects_candidate_until_three_nonempty_forward_windows_exist(tmp_path: Path):
    root=_optimizer_root(tmp_path);cfg=json.loads((root/'config/optimizer.json').read_text());cfg['gates']['minimum_evaluation_windows']=3;cfg['forward_evaluation']={'window_count':3,'minimum_opportunities_per_window':{'C':1,'S':1,'D':1,'R':1}};(root/'config/optimizer.json').write_text(json.dumps(cfg),encoding='utf-8');led=AppendOnlyCsvLedger(root/'ledger/closed_trades.csv',('sample_id','candidate_id'));led.append({'sample_id':'b1','opportunity_id':'o1','line':'C','candidate_id':'release_v2','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':'2026-02-01','exit_date':'2026-02-02','ret':0.01,'triggered':1,'regime':'neutral'});led.append({'sample_id':'c1','opportunity_id':'o1','line':'C','candidate_id':'C_DELAY1','decision_at':'2026-08-25T15:00:00+08:00','observable_at':'2026-08-25T15:00:00+08:00','entry_date':'2026-02-01','exit_date':'2026-02-02','ret':0.02,'triggered':1,'regime':'neutral'});gate=run_optimizer(root,'2026-08-26T16:00:00+08:00')['lines']['C']['candidates'][0]['gate'];assert 'MIN_EVAL_WINDOWS' in gate['reasons']
